-- The icustays16 table generated by the following code contains all ICU records with los of at least 1 day, 74824 records in total.
-- This section does not filter patients' diagnoses or disease information, nor does it select the first ICU record for the same patient, to improve generalizability.

-- This block removes duplicate ICU records: when the same subject_id has multiple repeated ICU admissions, only the first is kept and the rest are removed. This section has been commented out to improve generalizability. This is because the multiple admissions of the same patient have different diagnosis lists; if only the first ICU record were kept, that record might lack the specified diagnosis and thus exclude the patient entirely, even though a later ICU record for the same patient might contain the target diagnosis.
-- DROP TABLE IF EXISTS public.icustays3;
-- CREATE TABLE public.icustays3 AS
-- WITH icutemp AS
-- (SELECT *,
--  ROW_NUMBER() OVER (PARTITION BY subject_id ORDER BY intime) AS stay_order
--  FROM public.icustays2)
-- SELECT subject_id, hadm_id, stay_id, intime, outtime, los
--     FROM icutemp
--     WHERE stay_order = 1;
-- SELECT COUNT(*) FROM public.icustays3;

-- The icustays table contains a total of 94458 ICU admission records
SELECT COUNT(*) FROM mimiciv_icu.icustays; --94458
-- Remove records with los less than 1 day, resulting in 74829 ICU admission records
DROP TABLE IF EXISTS public.icustays2;
CREATE TABLE public.icustays2 AS
SELECT subject_id, hadm_id, stay_id, intime, outtime, los
FROM mimiciv_icu.icustays
WHERE los >= 1;
SELECT COUNT(*) FROM public.icustays2; --74829

-- Add survival data.
-- Add the discharge time of the last admission to the patients table, generating the patients2 table.
DROP TABLE IF EXISTS public.patients2;
CREATE TABLE public.patients2 AS
SELECT 
    pa.*, 
    MAX(ad.dischtime) AS last_dischtime    
FROM mimiciv_hosp.patients AS pa
LEFT JOIN mimiciv_hosp.admissions AS ad
ON pa.subject_id = ad.subject_id
GROUP BY pa.subject_id;
SELECT COUNT(*) FROM mimiciv_hosp.patients; --364627
SELECT COUNT(last_dischtime) FROM public.patients2; --223452. Not all patients have admission records.
-- Extract the time of death from the dod variable in the patients table. Note that deathtime from the admissions table should not be used as the time of death, because it refers to death during the hospitalization.
-- Determine the follow-up cutoff time. If dod is not null, the patient ultimately died; the follow-up cutoff time is dod and the status is 1 (dead). If dod is null, the status is 0 (survived), and the follow-up cutoff time is the discharge time of the patient's last admission plus 1 year.
-- The MIMIC database only has the date of death, not an exact time point. Based on later experience, the time of death is set to 23:59:59 on the day of dod, to avoid as much as possible the situation where the time of death precedes the admission time.
-- Add survival status and survival time
DROP TABLE IF EXISTS public.icustays3;
CREATE TABLE public.icustays3 AS
SELECT ie.*, 
    (DATE_TRUNC('day', pa.dod) + INTERVAL '23 hours 59 minutes 59 seconds')::TIMESTAMP AS tod,
    CASE
        WHEN pa.dod IS NOT NULL THEN 1
        ELSE 0
    END AS survival_status,
    CASE
        WHEN pa.dod IS NOT NULL THEN (DATE_TRUNC('day', pa.dod) + INTERVAL '23 hours 59 minutes 59 seconds')::TIMESTAMP
        ELSE pa.last_dischtime + INTERVAL '1 year'
    END AS survival_time
FROM public.icustays2 AS ie
LEFT JOIN public.patients2 AS pa
ON ie.subject_id = pa.subject_id;
SELECT COUNT(survival_time) FROM public.icustays3; --74829

-- Calculate prognostic indicators such as survival days, 30-day death, and 1-year death. Use the interval between the time of death and intime to determine whether death occurred within 30 days or 1 year after ICU admission.
DROP TABLE IF EXISTS public.icustays4;
CREATE TABLE public.icustays4 AS
SELECT *,
    EXTRACT(EPOCH FROM (survival_time - intime)) / 86400 AS survival_day,
    CASE 
        WHEN tod IS NULL THEN 0
        WHEN tod > intime + INTERVAL '30 DAY' THEN 0
        WHEN tod <= intime + INTERVAL '30 DAY' 
            AND tod > intime THEN 1
        ELSE 0
    END AS thirty_day_death,
    CASE
        WHEN tod IS NULL THEN 0
        WHEN tod > intime + INTERVAL '1 YEAR' THEN 0
        WHEN tod <= intime + INTERVAL '1 YEAR' 
            AND tod > intime THEN 1
        ELSE 0
    END AS one_year_death
FROM public.icustays3;
-- Found 5 records with negative survival_day
SELECT * FROM public.icustays4
WHERE survival_day < 0;
-- After removing records with negative survival_day, 74824 records remain
DELETE FROM public.icustays4 
WHERE survival_day < 0;
SELECT COUNT(*) FROM public.icustays4;

-- Add hospital_expire_flag, insurance, race
-- Querying shows that MIMIC has 33 different types of race; following the NHANES approach, they are merged into 6 different categories: Mexican American, Other Hispanic, Non-Hispanic White, Non-Hispanic Black, Non-Hispanic Asian, Other Race - Including Multi-Racial
DROP TABLE IF EXISTS public.icustays5;
CREATE TABLE public.icustays5 AS
SELECT ie.*, ad.hospital_expire_flag, ad.insurance,
    CASE 
        WHEN ad.race IN ('PATIENT DECLINED TO ANSWER', 'UNABLE TO OBTAIN', 'UNKNOWN') 
             THEN 'Unknown or Not Reported'
        WHEN ad.race LIKE 'HISPANIC%' OR ad.race = 'SOUTH AMERICAN' THEN 'Hispanic'
        WHEN ad.race LIKE 'WHITE%' OR ad.race = 'PORTUGUESE' THEN 'Non-Hispanic White'
        WHEN ad.race IN ('BLACK/AFRICAN', 'BLACK/AFRICAN AMERICAN', 'BLACK/CAPE VERDEAN', 'BLACK/CARIBBEAN ISLAND') 
             THEN 'Non-Hispanic Black'
        WHEN ad.race LIKE 'ASIAN%' THEN 'Non-Hispanic Asian'
        ELSE 'Other Race - Including Multi-Racial'
    END AS race
FROM public.icustays4 AS ie
LEFT JOIN mimiciv_hosp.admissions AS ad
ON ie.hadm_id = ad.hadm_id;

-- Add age, gender
DROP TABLE IF EXISTS public.icustays6;
CREATE TABLE public.icustays6 AS
SELECT ie.*,
    pa.anchor_age + EXTRACT(EPOCH FROM ie.intime - MAKE_TIMESTAMP(pa.anchor_year, 1, 1, 0, 0, 0)) / 31556908.8 AS age,
    pa.gender
FROM public.icustays5 AS ie
LEFT JOIN mimiciv_hosp.patients AS pa
ON ie.subject_id = pa.subject_id;

-- Look up weight and BMI
-- Note: in the official code, first_day_height and first_day_weight take the average of multiple measurements within the time window, but first_day_lab later takes the maximum and minimum values
-- Obtain height from the first_day_height table
DROP TABLE IF EXISTS public.icustays7;
CREATE TABLE public.icustays7 AS
SELECT ie.*, he.height
FROM public.icustays6 AS ie
LEFT JOIN mimiciv_derived.first_day_height AS he
ON ie.stay_id = he.stay_id;
SELECT COUNT(height) FROM public.icustays7; -- 36455 height records

-- Obtain weight data from the first_day_weight table and calculate BMI
DROP TABLE IF EXISTS public.icustays8;
CREATE TABLE public.icustays8 AS
SELECT ie.*, we.weight, we.weight/(ie.height^2)*10000 AS BMI
FROM public.icustays7 AS ie
LEFT JOIN mimiciv_derived.first_day_weight AS we
ON ie.stay_id = we.stay_id;
SELECT COUNT(weight) FROM public.icustays8; -- 72922 weight records
SELECT COUNT(BMI) FROM public.icustays8; -- 36395 BMI records

-- Add the Charlson comorbidity index and several medical history items
DROP TABLE IF EXISTS public.icustays9;
CREATE TABLE public.icustays9 AS
SELECT 
    ie.*, cs.charlson_comorbidity_index, 
    cs.renal_disease,
    cs.severe_liver_disease, 
    cs.metastatic_solid_tumor AS metastatic_cancer, 
    cs.aids
FROM public.icustays8 AS ie
LEFT JOIN mimiciv_derived.charlson AS cs
ON ie.hadm_id = cs.hadm_id;

-- Add the APSIII score
DROP TABLE IF EXISTS public.icustays10;
CREATE TABLE public.icustays10 AS
SELECT ie.*, aps.apsiii
FROM public.icustays9 AS ie
LEFT JOIN mimiciv_derived.apsiii AS aps
ON ie.stay_id = aps.stay_id;

-- Obtain the gcs_min score from first_day_gcs
DROP TABLE IF EXISTS public.icustays11;
CREATE TABLE public.icustays11 AS
SELECT ie.*, gcs.gcs_min
FROM public.icustays10 AS ie
LEFT JOIN mimiciv_derived.first_day_gcs AS gcs
ON ie.stay_id = gcs.stay_id;

-- Add the first non-null gcs value within the ICU first-day time window
DROP TABLE IF EXISTS public.icustays12;
CREATE TABLE public.icustays12 AS
-- First CTE: filter non-null gcs records within the time window (basic filtering)
WITH temp1 AS (
    SELECT 
        gc.stay_id,
        gc.gcs,
        gc.charttime,
        ie.intime
    FROM mimiciv_derived.gcs AS gc
    INNER JOIN mimiciv_icu.icustays AS ie 
        ON gc.stay_id = ie.stay_id
    WHERE 
        gc.gcs IS NOT NULL
        AND gc.charttime BETWEEN (ie.intime - INTERVAL '6 HOUR') 
                             AND (ie.intime + INTERVAL '1 DAY')
),
-- Second CTE: based on temp1, take the first gcs record for each stay_id (in ascending time order)
temp2 AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        gcs
    FROM temp1
    ORDER BY stay_id, charttime ASC  -- group first, then take the first record by time
)
-- Main query: create the new table, left join to retain all records of the original table
SELECT 
    ie.*,
    temp2.gcs AS gcs_first  -- automatically NULL when there is no matching record
FROM public.icustays11 AS ie
LEFT JOIN temp2 
    ON ie.stay_id = temp2.stay_id;
-- In fact, temp1 and temp2 above can be merged

-- Add the LODS score
DROP TABLE IF EXISTS public.icustays13;
CREATE TABLE public.icustays13 AS
SELECT ie.*, lo.lods
FROM public.icustays12 AS ie
LEFT JOIN mimiciv_derived.lods AS lo
ON ie.stay_id = lo.stay_id;

-- Add the OASIS score
DROP TABLE IF EXISTS public.icustays14;
CREATE TABLE public.icustays14 AS
SELECT ie.*, oa.oasis
FROM public.icustays13 AS ie
LEFT JOIN mimiciv_derived.oasis AS oa
ON ie.stay_id = oa.stay_id;

-- Add the SAPS II score
DROP TABLE IF EXISTS public.icustays15;
CREATE TABLE public.icustays15 AS
SELECT ie.*, sa.sapsii
FROM public.icustays14 AS ie
LEFT JOIN mimiciv_derived.sapsii AS sa
ON ie.stay_id = sa.stay_id;

-- Obtain the sofa score from first_day_sofa
DROP TABLE IF EXISTS public.icustays16;
CREATE TABLE public.icustays16 AS
SELECT ie.*, so.sofa
FROM public.icustays15 AS ie
LEFT JOIN mimiciv_derived.first_day_sofa AS so
ON ie.stay_id = so.stay_id;

---------------------------------------------------------------------------------------------------------
-- Add vital sign means and one worst extreme value
DROP TABLE IF EXISTS public.icustays17;
CREATE TABLE public.icustays17 AS
SELECT ie.*, 
    vs.heart_rate_mean, 
    vs.sbp_mean, 
    vs.dbp_mean, 
    vs.mbp_mean, 
    vs.resp_rate_mean, 
    vs.temperature_mean,
    vs.spo2_mean,
    vs.heart_rate_max, 
    vs.sbp_min, 
    vs.dbp_min, 
    vs.mbp_min, 
    vs.resp_rate_max, 
    vs.temperature_max,
    vs.spo2_min    
FROM public.icustays16 AS ie
LEFT JOIN mimiciv_derived.first_day_vitalsign AS vs
ON ie.stay_id = vs.stay_id;

-- Add the first vital sign measurements
DROP TABLE IF EXISTS public.icustays18;
CREATE TABLE public.icustays18 AS
WITH 
-- 1. Calculate the earliest non-null heart rate for each stay_id
first_hr AS (
    SELECT DISTINCT ON (vs.stay_id)
        vs.stay_id,
        vs.heart_rate AS heart_rate_first
    FROM mimiciv_derived.vitalsign AS vs
    JOIN mimiciv_icu.icustays AS ie 
    ON vs.stay_id = ie.stay_id
    WHERE vs.heart_rate IS NOT NULL  -- keep only records with a value
      AND vs.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                           AND ie.intime + INTERVAL '1 DAY'
    ORDER BY vs.stay_id, vs.charttime ASC
),
-- 2. Calculate the earliest non-null systolic blood pressure (sbp) for each stay_id
first_sbp AS (
    SELECT DISTINCT ON (vs.stay_id)
        vs.stay_id,
        vs.sbp AS sbp_first
    FROM mimiciv_derived.vitalsign AS vs
    JOIN mimiciv_icu.icustays AS ie 
    ON vs.stay_id = ie.stay_id
    WHERE vs.sbp IS NOT NULL
      AND vs.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                           AND ie.intime + INTERVAL '1 DAY'
    ORDER BY vs.stay_id, vs.charttime ASC
),
-- 3. Calculate the earliest non-null diastolic blood pressure (dbp) for each stay_id
first_dbp AS (
    SELECT DISTINCT ON (vs.stay_id)
        vs.stay_id,
        vs.dbp AS dbp_first
    FROM mimiciv_derived.vitalsign AS vs
    JOIN mimiciv_icu.icustays AS ie 
    ON vs.stay_id = ie.stay_id
    WHERE vs.dbp IS NOT NULL
      AND vs.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                           AND ie.intime + INTERVAL '1 DAY'
    ORDER BY vs.stay_id, vs.charttime ASC
),
-- 4. Calculate the earliest non-null mean arterial pressure (mbp) for each stay_id
first_mbp AS (
    SELECT DISTINCT ON (vs.stay_id)
        vs.stay_id,
        vs.mbp AS mbp_first
    FROM mimiciv_derived.vitalsign AS vs
    JOIN mimiciv_icu.icustays AS ie 
    ON vs.stay_id = ie.stay_id
    WHERE vs.mbp IS NOT NULL
      AND vs.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                           AND ie.intime + INTERVAL '1 DAY'
    ORDER BY vs.stay_id, vs.charttime ASC
),
-- 5. Calculate the earliest non-null respiratory rate (resp_rate) for each stay_id
first_rr AS (
    SELECT DISTINCT ON (vs.stay_id)
        vs.stay_id,
        vs.resp_rate AS resp_rate_first
    FROM mimiciv_derived.vitalsign AS vs
    JOIN mimiciv_icu.icustays AS ie 
    ON vs.stay_id = ie.stay_id
    WHERE vs.resp_rate IS NOT NULL
      AND vs.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                           AND ie.intime + INTERVAL '1 DAY'
    ORDER BY vs.stay_id, vs.charttime ASC
),
-- 6. Calculate the earliest non-null temperature for each stay_id
first_temp AS (
    SELECT DISTINCT ON (vs.stay_id)
        vs.stay_id,
        vs.temperature AS temperature_first
    FROM mimiciv_derived.vitalsign AS vs
    JOIN mimiciv_icu.icustays AS ie 
    ON vs.stay_id = ie.stay_id
    WHERE vs.temperature IS NOT NULL
      AND vs.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                           AND ie.intime + INTERVAL '1 DAY'
    ORDER BY vs.stay_id, vs.charttime ASC
),
-- 7. Calculate the earliest non-null oxygen saturation (spo2) for each stay_id
first_spo2 AS (
    SELECT DISTINCT ON (vs.stay_id)
        vs.stay_id,
        vs.spo2 AS spo2_first
    FROM mimiciv_derived.vitalsign AS vs
    JOIN mimiciv_icu.icustays AS ie 
    ON vs.stay_id = ie.stay_id
    WHERE vs.spo2 IS NOT NULL
      AND vs.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                           AND ie.intime + INTERVAL '1 DAY'
    ORDER BY vs.stay_id, vs.charttime ASC
)
-- Main query: left join all separately calculated earliest vital sign values to the main table
SELECT 
    ie.*,
    fh.heart_rate_first,
    fs.sbp_first,
    fd.dbp_first,
    fm.mbp_first,
    fr.resp_rate_first,
    ft.temperature_first,
    fspo2.spo2_first
FROM public.icustays17 AS ie
-- Left join each earliest vital sign value one by one to ensure no main-table records are lost
LEFT JOIN first_hr   AS fh    ON ie.stay_id = fh.stay_id
LEFT JOIN first_sbp  AS fs    ON ie.stay_id = fs.stay_id
LEFT JOIN first_dbp  AS fd    ON ie.stay_id = fd.stay_id
LEFT JOIN first_mbp  AS fm    ON ie.stay_id = fm.stay_id
LEFT JOIN first_rr   AS fr    ON ie.stay_id = fr.stay_id
LEFT JOIN first_temp AS ft    ON ie.stay_id = ft.stay_id
LEFT JOIN first_spo2 AS fspo2 ON ie.stay_id = fspo2.stay_id;

-- Add urine output
DROP TABLE IF EXISTS public.icustays19;
CREATE TABLE public.icustays19 AS
SELECT ie.*, uo.urineoutput    
FROM public.icustays18 AS ie
LEFT JOIN mimiciv_derived.first_day_urine_output AS uo
ON ie.stay_id = uo.stay_id;

---------------------------------------------------------------------------------------------------------
-- Add laboratory results. First prepare the various laboratory result tables needed, then join them to the main table.
-- Based on the mimiciv_derived.complete_blood_count table, extract the aggregated values of the complete blood count on the first day of ICU admission (extracting only data not included in first_day_lab), named cbc_p1
DROP TABLE IF EXISTS public.cbc_p1;  
CREATE TABLE public.cbc_p1 AS
SELECT
  ie.subject_id,
  ie.stay_id,
  MIN(mch) AS mch_min,
  MAX(mch) AS mch_max,
  MIN(mchc) AS mchc_min,
  MAX(mchc) AS mchc_max,
  MIN(mcv) AS mcv_min,
  MAX(mcv) AS mcv_max,
  MIN(rbc) AS rbc_min,
  MAX(rbc) AS rbc_max,
  MIN(rdw) AS rdw_min,
  MAX(rdw) AS rdw_max,
  MIN(rdwsd) AS rdwsd_min,
  MAX(rdwsd) AS rdwsd_max
FROM mimiciv_icu.icustays AS ie
LEFT JOIN mimiciv_derived.complete_blood_count AS cbc
  ON ie.subject_id = cbc.subject_id
  AND cbc.charttime >= ie.intime - INTERVAL '6 HOUR'
  AND cbc.charttime <= ie.intime + INTERVAL '1 DAY'
GROUP BY
  ie.subject_id,
  ie.stay_id;

-- Based on the mimiciv_derived.complete_blood_count table, extract the first values of the complete blood count on the first day of ICU admission, generating the cbc_p2 table
DROP TABLE IF EXISTS public.cbc_p2;  
CREATE TABLE public.cbc_p2 AS
WITH cbc_time_filtered AS (
    -- Step 1: join the tables and filter the time window, keeping the base data
    SELECT 
        ie.stay_id,
        cbc.charttime,
        cbc.hematocrit,
        cbc.hemoglobin,
        cbc.mch,
        cbc.mchc,
        cbc.mcv,
        cbc.platelet,
        cbc.rbc,
        cbc.rdw,
        cbc.rdwsd,
        cbc.wbc
    FROM mimiciv_icu.icustays AS ie 
    LEFT JOIN mimiciv_derived.complete_blood_count AS cbc
        ON cbc.subject_id = ie.subject_id
        AND cbc.hadm_id = ie.hadm_id  -- additional join condition to avoid matching across admissions
        AND cbc.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                              AND ie.intime + INTERVAL '1 DAY'
),
-- Extract the "first non-null value under stay_id" separately for each indicator
hct_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        hematocrit AS hematocrit_first
    FROM cbc_time_filtered
    WHERE hematocrit IS NOT NULL  -- filter NULL values
    ORDER BY stay_id, charttime ASC  -- in ascending time order, take the first record
),
hgb_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        hemoglobin AS hemoglobin_first
    FROM cbc_time_filtered
    WHERE hemoglobin IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
mch_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        mch AS mch_first
    FROM cbc_time_filtered
    WHERE mch IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
mchc_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        mchc AS mchc_first
    FROM cbc_time_filtered
    WHERE mchc IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
mcv_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        mcv AS mcv_first
    FROM cbc_time_filtered
    WHERE mcv IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
platelet_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        platelet AS platelet_first
    FROM cbc_time_filtered
    WHERE platelet IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
rbc_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        rbc AS rbc_first
    FROM cbc_time_filtered
    WHERE rbc IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
rdw_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        rdw AS rdw_first
    FROM cbc_time_filtered
    WHERE rdw IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
rdwsd_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        rdwsd AS rdwsd_first
    FROM cbc_time_filtered
    WHERE rdwsd IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
wbc_first AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        wbc AS wbc_first
    FROM cbc_time_filtered
    WHERE wbc IS NOT NULL
    ORDER BY stay_id, charttime ASC
)
-- Finally join all indicators, ensuring every stay_id is retained (LEFT JOIN)
SELECT 
    ie.stay_id,
    hct.hematocrit_first,
    hgb.hemoglobin_first,
    mch.mch_first,
    mchc.mchc_first,
    mcv.mcv_first,
    plt.platelet_first,
    rbc.rbc_first,
    rdw.rdw_first,
    rdwsd.rdwsd_first,
    wbc.wbc_first
FROM mimiciv_icu.icustays AS ie
LEFT JOIN hct_first AS hct ON ie.stay_id = hct.stay_id
LEFT JOIN hgb_first AS hgb ON ie.stay_id = hgb.stay_id
LEFT JOIN mch_first AS mch ON ie.stay_id = mch.stay_id
LEFT JOIN mchc_first AS mchc ON ie.stay_id = mchc.stay_id
LEFT JOIN mcv_first AS mcv ON ie.stay_id = mcv.stay_id
LEFT JOIN platelet_first AS plt ON ie.stay_id = plt.stay_id
LEFT JOIN rbc_first AS rbc ON ie.stay_id = rbc.stay_id
LEFT JOIN rdw_first AS rdw ON ie.stay_id = rdw.stay_id
LEFT JOIN rdwsd_first AS rdwsd ON ie.stay_id = rdwsd.stay_id
LEFT JOIN wbc_first AS wbc ON ie.stay_id = wbc.stay_id;

-- Based on the mimiciv_derived.blood_differential table, extract the first values of the complete blood count on the first day of ICU admission, generating the cbc_p3 table
DROP TABLE IF EXISTS public.cbc_p3;  
CREATE TABLE public.cbc_p3 AS
WITH blood_differential_filtered AS (
    SELECT 
        ie.stay_id,
        bd.charttime,
        bd.wbc,
        bd.neutrophils,
        bd.lymphocytes
    FROM mimiciv_icu.icustays AS ie 
    LEFT JOIN mimiciv_derived.blood_differential AS bd
        ON bd.subject_id = ie.subject_id
        AND bd.hadm_id = ie.hadm_id
        AND bd.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                              AND ie.intime + INTERVAL '1 DAY'
),
first_wbc AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        wbc AS wbc_first
    FROM blood_differential_filtered
    WHERE wbc IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_neutrophils AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        neutrophils AS neutrophils_first
    FROM blood_differential_filtered
    WHERE neutrophils IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_lymphocytes AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        lymphocytes AS lymphocytes_first
    FROM blood_differential_filtered
    WHERE lymphocytes IS NOT NULL
    ORDER BY stay_id, charttime ASC
)
SELECT 
    ie.stay_id,
    first_wbc.wbc_first,
    first_neutrophils.neutrophils_first,
    first_lymphocytes.lymphocytes_first
FROM mimiciv_icu.icustays AS ie
LEFT JOIN first_wbc ON ie.stay_id = first_wbc.stay_id
LEFT JOIN first_neutrophils ON ie.stay_id = first_neutrophils.stay_id
LEFT JOIN first_lymphocytes ON ie.stay_id = first_lymphocytes.stay_id;

-- Based on the chemistry table, extract the first values of the biochemistry data on the first day of ICU admission, generating the chemistry_first table
DROP TABLE IF EXISTS public.chemistry_first;  
CREATE TABLE public.chemistry_first AS
WITH chemistry_filtered AS (
    SELECT 
        ie.stay_id,
        ch.charttime,
        ch.albumin, ch.aniongap, ch.bicarbonate, ch.bun,
        ch.calcium, ch.chloride, ch.creatinine, ch.glucose,
        ch.sodium, ch.potassium
    FROM mimiciv_icu.icustays AS ie 
    LEFT JOIN mimiciv_derived.chemistry AS ch
        ON ch.subject_id = ie.subject_id
        AND ch.hadm_id = ie.hadm_id  -- additional join condition to avoid matching across admissions
        AND ch.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                              AND ie.intime + INTERVAL '1 DAY'
),
first_albumin AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        albumin AS albumin_first
    FROM chemistry_filtered
    WHERE albumin IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_aniongap AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        aniongap AS aniongap_first
    FROM chemistry_filtered
    WHERE aniongap IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_bicarbonate AS (
    SELECT DISTINCT ON (stay_id)
