    WHERE bicarbonate IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_lactate AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        lactate AS lactate_first
    FROM bg_filtered
    WHERE lactate IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_pco2 AS (
    SELECT DISTINCT ON (stay_id)
