LEFT JOIN first_bicarbonate ON ie.stay_id = first_bicarbonate.stay_id
LEFT JOIN first_lactate ON ie.stay_id = first_lactate.stay_id
LEFT JOIN first_pco2 ON ie.stay_id = first_pco2.stay_id
LEFT JOIN first_po2 ON ie.stay_id = first_po2.stay_id
LEFT JOIN first_ph ON ie.stay_id = first_ph.stay_id
LEFT JOIN first_pao2fio2ratio ON ie.stay_id = first_pao2fio2ratio.stay_id;

