-- Create the first_day_phosphate table
-- Find the test itemid corresponding to phosphate
SELECT * FROM mimiciv_hosp.d_labitems
WHERE LOWER(label) LIKE '%phosphate%'; --50970
-- Add phosphate. The reason the other parameters are aggregated with MAX grouped by le.specimen_id here is that, in principle, a single specimen should have only one result for a given test, but it is possible that because the first measurement was inaccurate, the remaining sample was used to run the test again, in which case taking the last measurement would be more accurate. However, the official MIMIC code does not take the last measurement; it takes the MAX instead, to simplify the code.
DROP TABLE IF EXISTS public.phosphate; 
CREATE TABLE public.phosphate AS
SELECT
  MAX(subject_id) AS subject_id,
  MAX(hadm_id) AS hadm_id,
  MAX(charttime) AS charttime,
  le.specimen_id, 
  MAX(valuenum) AS phosphate
FROM mimiciv_hosp.labevents AS le
WHERE
  le.itemid = 50970
  AND NOT valuenum IS NULL
  AND valuenum > 0
GROUP BY le.specimen_id;
-- Generate first_day_phosphate
DROP TABLE IF EXISTS public.first_day_phosphate;  
CREATE TABLE public.first_day_phosphate AS
WITH phosphate_filtered AS (
    SELECT 
        ie.stay_id,
        ph.charttime,
        ph.phosphate
    FROM mimiciv_icu.icustays AS ie 
    LEFT JOIN public.phosphate AS ph
        ON ph.subject_id = ie.subject_id
        AND ph.hadm_id = ie.hadm_id
        AND ph.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                              AND ie.intime + INTERVAL '1 DAY'
),
first_phosphate AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        phosphate AS phosphate_first
    FROM phosphate_filtered
    WHERE phosphate IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
minmax_phosphate AS (
    SELECT 
        stay_id,
        MIN(phosphate) AS phosphate_min,
        MAX(phosphate) AS phosphate_max
    FROM phosphate_filtered
    GROUP BY stay_id
)
SELECT 
    ie.stay_id,
    first_phosphate.phosphate_first,
    minmax_phosphate.phosphate_min,
    minmax_phosphate.phosphate_max
FROM mimiciv_icu.icustays AS ie
LEFT JOIN first_phosphate ON ie.stay_id = first_phosphate.stay_id
LEFT JOIN minmax_phosphate ON ie.stay_id = minmax_phosphate.stay_id;

-- Based on the enzyme table, extract the first values of the enzyme data on the first day of ICU admission, generating the enzyme_first table
DROP TABLE IF EXISTS public.enzyme_first;  
CREATE TABLE public.enzyme_first AS
WITH enzyme_filtered AS (
    SELECT 
        ie.stay_id,
        en.charttime,
        en.alt,
        en.alp,
        en.ast,
        en.bilirubin_total,
        en.ck_cpk AS ck,
        en.ck_mb,
        en.ggt,
        en.ld_ldh AS ldh
    FROM mimiciv_icu.icustays AS ie 
    LEFT JOIN mimiciv_derived.enzyme AS en
        ON en.subject_id = ie.subject_id
        AND en.hadm_id = ie.hadm_id
        AND en.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                              AND ie.intime + INTERVAL '1 DAY'
),
first_alt AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        alt AS alt_first
    FROM enzyme_filtered
    WHERE alt IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_alp AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        alp AS alp_first
    FROM enzyme_filtered
    WHERE alp IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_ast AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        ast AS ast_first
    FROM enzyme_filtered
    WHERE ast IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_bilirubin_total AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        bilirubin_total AS bilirubin_total_first
    FROM enzyme_filtered
    WHERE bilirubin_total IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_ck AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        ck AS ck_first
    FROM enzyme_filtered
    WHERE ck IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_ck_mb AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        ck_mb AS ck_mb_first
    FROM enzyme_filtered
    WHERE ck_mb IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_ggt AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        ggt AS ggt_first
    FROM enzyme_filtered
    WHERE ggt IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_ldh AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        ldh AS ldh_first
    FROM enzyme_filtered
    WHERE ldh IS NOT NULL
    ORDER BY stay_id, charttime ASC
)
SELECT 
    ie.stay_id,
    first_alt.alt_first,
    first_alp.alp_first,
    first_ast.ast_first,
    first_bilirubin_total.bilirubin_total_first,
    first_ck.ck_first,
    first_ck_mb.ck_mb_first,
    first_ggt.ggt_first,
    first_ldh.ldh_first    
FROM mimiciv_icu.icustays AS ie
LEFT JOIN first_alt ON ie.stay_id = first_alt.stay_id
LEFT JOIN first_alp ON ie.stay_id = first_alp.stay_id
LEFT JOIN first_ast ON ie.stay_id = first_ast.stay_id
LEFT JOIN first_bilirubin_total ON ie.stay_id = first_bilirubin_total.stay_id
LEFT JOIN first_ck ON ie.stay_id = first_ck.stay_id
LEFT JOIN first_ck_mb ON ie.stay_id = first_ck_mb.stay_id
LEFT JOIN first_ggt ON ie.stay_id = first_ggt.stay_id
LEFT JOIN first_ldh ON ie.stay_id = first_ldh.stay_id;

-- Based on the coagulation table, extract the first values of the coagulation data on the first day of ICU admission, generating the coagulation_first table
DROP TABLE IF EXISTS public.coagulation_first;  
CREATE TABLE public.coagulation_first AS
WITH coagulation_filtered AS (
    SELECT 
        ie.stay_id,
        co.charttime,
        co.inr,
        co.pt,
        co.ptt
    FROM mimiciv_icu.icustays AS ie 
    LEFT JOIN mimiciv_derived.coagulation AS co
        ON co.subject_id = ie.subject_id
        AND co.hadm_id = ie.hadm_id
        AND co.charttime BETWEEN ie.intime - INTERVAL '6 HOUR' 
                              AND ie.intime + INTERVAL '1 DAY'
),
first_inr AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        inr AS inr_first
    FROM coagulation_filtered
    WHERE inr IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_pt AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        pt AS pt_first
    FROM coagulation_filtered
    WHERE pt IS NOT NULL
    ORDER BY stay_id, charttime ASC
),
first_ptt AS (
    SELECT DISTINCT ON (stay_id)
        stay_id,
        ptt AS ptt_first
    FROM coagulation_filtered
    WHERE ptt IS NOT NULL
    ORDER BY stay_id, charttime ASC
)
SELECT 
    ie.stay_id,
    first_inr.inr_first,
    first_pt.pt_first,
    first_ptt.ptt_first
FROM mimiciv_icu.icustays AS ie
LEFT JOIN first_inr ON ie.stay_id = first_inr.stay_id
LEFT JOIN first_pt ON ie.stay_id = first_pt.stay_id
LEFT JOIN first_ptt ON ie.stay_id = first_ptt.stay_id;

