-- Add laboratory items from the following tables:
--mimiciv_derived.first_day_lab  extreme values of complete blood count, biochemistry, coagulation, and enzymes
--mimiciv_derived.first_day_bg_art  bg first values   
--public.cbc_p1  complete blood count extreme values not covered by first_day_lab
--public.first_day_phosphate    phosphate extreme values and first values
--public.cbc_p2  complete blood count first values (excluding white blood cells)
--public.cbc_p3  first values of white blood cells, neutrophils, and lymphocytes in the complete blood count
--public.chemistry_first    biochemistry first values (fewer items)
--public.coagulation_first  coagulation first values
--public.enzyme_first   enzyme first values
--public.bg_first or bg_first_art or bg_first_artcv   bg first values


-- Add extreme values----------------------------------------------------------
-- Add laboratory extreme values from mimiciv_derived.first_day_lab
DROP TABLE IF EXISTS public.icustays20;
CREATE TABLE public.icustays20 AS
SELECT 
    ie.*, 
    l.albumin_min, l.alp_max, l.alt_max, l.aniongap_max, l.bun_max, 
    l.bicarbonate_min, l.calcium_min, l.chloride_max, l.creatinine_max, 
    l.glucose_max, l.hemoglobin_min, l.inr_max, l.ld_ldh_max AS ldh_max, 
    l.platelets_min, l.potassium_max, l.ptt_max, l.sodium_max, 
    l.bilirubin_total_max, l.wbc_max    
FROM public.icustays19 AS ie
LEFT JOIN mimiciv_derived.first_day_lab AS l
ON ie.stay_id = l.stay_id;

-- Add blood gas extreme values from first_day_bg (without restricting blood sampling site, excluding pco2 and po2)
DROP TABLE IF EXISTS public.icustays21;
CREATE TABLE public.icustays21 AS
SELECT 
    ie.*, 
    b.baseexcess_min, b.lactate_max, b.ph_min
FROM public.icustays20 AS ie
LEFT JOIN mimiciv_derived.first_day_bg AS b
ON ie.stay_id = b.stay_id;

-- Add blood gas extreme values from first_day_bg_art (including pco2 and po2)
DROP TABLE IF EXISTS public.icustays_s1;
CREATE TABLE public.icustays_s1 AS
SELECT 
    ie.*, 
    b.po2_min, pco2_max, pao2fio2ratio_min
FROM public.icustays21 AS ie
LEFT JOIN mimiciv_derived.first_day_bg_art AS b
ON ie.stay_id = b.stay_id;

-- Add other complete blood count extreme values from public.cbc_p1
DROP TABLE IF EXISTS public.icustays22;
CREATE TABLE public.icustays22 AS
SELECT 
    ie.*, 
    cbc.mchc_min, cbc.mcv_min, cbc.rdw_max
FROM public.icustays_s1 AS ie
LEFT JOIN public.cbc_p1 AS cbc
ON ie.stay_id = cbc.stay_id;

-- Add phosphate extreme values and first values from public.first_day_phosphate
DROP TABLE IF EXISTS public.icustays23;
CREATE TABLE public.icustays23 AS
SELECT 
    ie.*, 
    ph.phosphate_min,
    ph.phosphate_first
FROM public.icustays22 AS ie
LEFT JOIN public.first_day_phosphate AS ph
ON ie.stay_id = ph.stay_id;

-- Add first values----------------------------------------------------------
-- Add complete blood count first values from public.cbc_p2 and public.cbc_p3
DROP TABLE IF EXISTS public.icustays24;
CREATE TABLE public.icustays24 AS
SELECT 
    ie.*, 
    c.hematocrit_first, c.hemoglobin_first, c.mch_first, c.mchc_first, 
    c.mcv_first, c.platelet_first, c.rbc_first, c.rdw_first, c.wbc_first,
    cb.neutrophils_first, cb.lymphocytes_first
FROM public.icustays23 AS ie
LEFT JOIN public.cbc_p2 AS c ON ie.stay_id = c.stay_id
LEFT JOIN public.cbc_p3 AS cb ON ie.stay_id = cb.stay_id;

-- Add biochemistry first values from public.chemistry_first (fewer items)
-- Add coagulation first values from public.coagulation_first
-- Add enzyme first values from public.enzyme_first
DROP TABLE IF EXISTS public.icustays25;
CREATE TABLE public.icustays25 AS
SELECT 
    ie.*, 
    ch.albumin_first, ch.aniongap_first, ch.bicarbonate_first, 
    ch.bun_first, ch.calcium_first, ch.chloride_first, 
    ch.creatinine_first, ch.glucose_first, ch.sodium_first, ch.potassium_first,
    co.inr_first, co.pt_first, co.ptt_first, 
    en.alt_first, en.alp_first, en.ast_first, en.bilirubin_total_first, 
    en.ck_first, en.ck_mb_first, en.ggt_first, en.ldh_first
FROM public.icustays24 AS ie
LEFT JOIN public.chemistry_first   AS ch ON ie.stay_id = ch.stay_id
LEFT JOIN public.coagulation_first AS co ON ie.stay_id = co.stay_id
LEFT JOIN public.enzyme_first      AS en ON ie.stay_id = en.stay_id;

-- Add bg first values from public.bg_first (without restricting blood sampling site, excluding pco2 and po2)
DROP TABLE IF EXISTS public.icustays26;
CREATE TABLE public.icustays26 AS
SELECT 
    ie.*, 
    bg.baseexcess_first, bg.lactate_first, bg.ph_first
FROM public.icustays25 AS ie
LEFT JOIN public.bg_first AS bg ON ie.stay_id = bg.stay_id;

-- Add bg first values from public.bg_first_art (including pco2 and po2)
DROP TABLE IF EXISTS public.icustays_s2;
CREATE TABLE public.icustays_s2 AS
SELECT 
    ie.*, 
    bg.po2_first, bg.pco2_first, bg.pao2fio2ratio_first
FROM public.icustays26 AS ie
LEFT JOIN public.bg_first_art AS bg 
ON ie.stay_id = bg.stay_id;

