-- This section, based on the vasoactive_agent table in the mimiciv_derived module combined with the icustays table, extracts vasoactive drug use on the first day of ICU admission (binary), named the first_day_vasoactive table.
DROP TABLE IF EXISTS public.first_day_vasoactive;
CREATE TABLE public.first_day_vasoactive AS
WITH icu_info AS (
    SELECT 
        subject_id,
        stay_id,        
        intime - INTERVAL '6 HOUR' AS first_day_starttime,
        intime + INTERVAL '1 DAY' AS first_day_endtime
    FROM mimiciv_icu.icustays
),
first_day_vasoactive AS (
    SELECT 
        va.stay_id,
        MAX(CASE 
            WHEN va.starttime <= ie.first_day_endtime
            AND va.endtime >= ie.first_day_starttime
            AND COALESCE(dopamine, epinephrine, norepinephrine, phenylephrine, vasopressin, dobutamine, milrinone) IS NOT NULL
            THEN 1 
            ELSE 0 
        END) AS vasoactive
    FROM mimiciv_derived.vasoactive_agent AS va
    INNER JOIN icu_info AS ie
    ON va.stay_id = ie.stay_id
    GROUP BY va.stay_id
)
SELECT 
    ie.subject_id,
    ie.stay_id,
    COALESCE(va.vasoactive, 0) AS vasoactive
FROM mimiciv_icu.icustays AS ie
LEFT JOIN first_day_vasoactive AS va 
ON ie.stay_id = va.stay_id;

-- Add medication information
DROP TABLE IF EXISTS public.icustays27;
CREATE TABLE public.icustays27 AS
SELECT 
    ie.*, 
    va.vasoactive
FROM public.icustays_s2 AS ie
LEFT JOIN public.first_day_vasoactive AS va
ON ie.stay_id = va.stay_id;

-- This section, based on the ventilation table in the mimiciv_derived module combined with the icustays table, extracts mechanical ventilation use on the first day of ICU admission (binary), named the first_day_mechanical_ventilation table. Mechanical ventilation includes tracheostomy, invasive ventilation, and non-invasive ventilation.
DROP TABLE IF EXISTS public.first_day_mechanical_ventilation;
CREATE TABLE public.first_day_mechanical_ventilation AS
WITH temp1 AS(
    SELECT 
        vl.stay_id,
        MAX(CASE 
            WHEN vl.ventilation_status IN ('Tracheostomy', 'InvasiveVent', 'NonInvasiveVent')
            AND vl.starttime <= ie.intime + INTERVAL '1 DAY'
            AND vl.endtime >= ie.intime - INTERVAL '6 HOUR'
            THEN 1 
            ELSE 0 
        END) AS mechanical_ventilation
    FROM mimiciv_derived.ventilation AS vl
    INNER JOIN mimiciv_icu.icustays AS ie
    ON vl.stay_id = ie.stay_id
    GROUP BY vl.stay_id
)
SELECT 
    ie.subject_id,
    ie.stay_id,
    COALESCE(temp1.mechanical_ventilation, 0) AS mechanical_ventilation
FROM mimiciv_icu.icustays AS ie
LEFT JOIN temp1 ON ie.stay_id = temp1.stay_id;

-- Add mechanical ventilation information
DROP TABLE IF EXISTS public.icustays28;
CREATE TABLE public.icustays28 AS
SELECT 
    ie.*, 
    mv.mechanical_ventilation
FROM public.icustays27 AS ie
LEFT JOIN public.first_day_mechanical_ventilation AS mv
ON ie.stay_id = mv.stay_id;

-- Add echocardiographic LVEF; note that lvef here is text type and needs to be converted to numeric in R later
DROP TABLE IF EXISTS public.icustays29;
CREATE TABLE public.icustays29 AS
WITH lvef_closest AS (
    SELECT DISTINCT ON (ie.stay_id)
        ie.stay_id,
        lv.lvef,
        lv.measurement_datetime AS lvef_meas_time
    FROM public.icustays28 ie
    INNER JOIN public.lvef lv
        ON ie.subject_id = lv.subject_id
    WHERE
        lv.measurement_datetime BETWEEN 
            ie.intime - INTERVAL '6 hours' 
            AND ie.intime + INTERVAL '24 hours'
        AND lv.lvef IS NOT NULL
    ORDER BY
        ie.stay_id,
        -- Convert the time difference to seconds, take the absolute value; the smaller the value, the closer to intime
        ABS(EXTRACT(EPOCH FROM (lv.measurement_datetime - ie.intime))) ASC
)
SELECT
    ie.*,
    lc.lvef
FROM public.icustays28 ie
LEFT JOIN lvef_closest lc
    ON ie.stay_id = lc.stay_id;
    
-- Add NT-proBNP 50963
DROP TABLE IF EXISTS public.icustays30;
CREATE TABLE public.icustays30 AS
SELECT DISTINCT ON (ie.stay_id)
    ie.*,
    le.valuenum AS ntprobnp
FROM public.icustays29 AS ie
LEFT JOIN mimiciv_hosp.labevents AS le
    ON ie.subject_id = le.subject_id
    AND le.itemid = 50963
    AND le.charttime 
        BETWEEN ie.intime - INTERVAL '6 hours'
            AND ie.intime + INTERVAL '24 hours'
    AND le.valuenum IS NOT NULL
ORDER BY ie.stay_id, le.charttime ASC;
